$ErrorActionPreference = 'Stop'
$Root = 'E:\BRODETAIL\autopilot'
$Target = Join-Path $Root 'issue39-apply-safe-v2-final.js'
$B64 = ''
$bytes = [Convert]::FromBase64String($B64)
$inputStream = New-Object System.IO.MemoryStream(,$bytes)
$gzip = New-Object System.IO.Compression.GzipStream($inputStream,[System.IO.Compression.CompressionMode]::Decompress)
$reader = New-Object System.IO.StreamReader($gzip,[Text.Encoding]::UTF8)
$js = $reader.ReadToEnd()
$reader.Dispose(); $gzip.Dispose(); $inputStream.Dispose()
[IO.File]::WriteAllText($Target,$js,(New-Object Text.UTF8Encoding($false)))
Write-Host "Created $Target"
& node $Target --root $Root
$code = $LASTEXITCODE
Write-Host "Finished with code $code"
Read-Host 'Press Enter to close'
exit $code
